// Built as a variable initialiser, not in an init(): fast.go's init computes
// descStateAt128 by calling fairplaySAPHash, which needs these tables, and Go
// runs every variable initialiser before any init().
var scrambleNib = buildScrambleNib()

func buildScrambleNib() (nib [32][16][2]uint64) {
	var rows [128][2]uint64
	for i := range rows {
		rows[i][0] = binary.LittleEndian.Uint64([]byte(scrambleRows)[i*16:])
		rows[i][1] = binary.LittleEndian.Uint64([]byte(scrambleRows)[i*16+8:])
	}
	var cols [128][2]uint64
	for ob := 0; ob < 128; ob++ {
		for ib := 0; ib < 128; ib++ {
			if rows[ob][ib>>6]>>uint(ib&63)&1 != 0 {
				cols[ib][ob>>6] |= 1 << uint(ob&63)
			}
		}
	}
	for n := 0; n < 32; n++ {
		for v := 0; v < 16; v++ {
			var acc [2]uint64
			for k := 0; k < 4; k++ {
				if v>>uint(k)&1 != 0 {
					c := &cols[n*4+k]
					acc[0] ^= c[0]
					acc[1] ^= c[1]
				}
			}
			nib[n][v] = acc
		}
	}
	return
}

func applyScramble(out *[16]byte) {
	var o0, o1 uint64
	for i := 0; i < 16; i++ {
		b := out[i]
		lo := &scrambleNib[i*2][b&0xf]
		hi := &scrambleNib[i*2+1][b>>4]
		o0 ^= lo[0] ^ hi[0]
		o1 ^= lo[1] ^ hi[1]
	}
	binary.LittleEndian.PutUint64(out[0:8], o0)
	binary.LittleEndian.PutUint64(out[8:16], o1)
}

// applyScrambleReference is the loop as it was written, kept as the oracle
// TestScrambleMatchesReference checks the table form against.
func applyScrambleReference(out *[16]byte) {
	for i := 0; i < 256; i++ {
		out[i&15] ^= bits.RotateLeft8(out[(i-7)&15], 1) ^
			bits.RotateLeft8(out[(i-5)&15], 6) ^
			bits.RotateLeft8(out[(i-1)&15], 5)
	}
}
